        <aside class="catalog-sidebar" style="width: 25%; min-width: 220px;">
            <h4>Filters</h4>

            <div class="filter-section">
                <h5>Categories</h5>
                @if (_categories is null)
                {
                    <p><em>Loading categories...</em></p>
                }
                else
                {
                    @foreach (var category in _categories)
                    {
                        <div class="form-check">
                            <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
                                   checked="@(_selectedCategories.Contains(category))"
                                   @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
                            <label class="form-check-label" for="@($"cat-{category}")">@category</label>
                        </div>
                    }
                }
            </div>

            <div class="filter-section" style="margin-top: 1rem;">
                <h5>Price Range</h5>
                <div class="mb-2">
                    <label for="minPrice" class="form-label">Min Price</label>
                    <input type="number" class="form-control" id="minPrice" step="0.01" min="0"
                           @bind="_minPrice" placeholder="0.00" />
                </div>
                <div class="mb-2">
                    <label for="maxPrice" class="form-label">Max Price</label>
                    <input type="number" class="form-control" id="maxPrice" step="0.01" min="0"
                           @bind="_maxPrice" placeholder="No limit" />
                </div>
            </div>

            <div class="filter-section" style="margin-top: 1rem;">
                <div class="form-check">
                    <input class="form-check-input" type="checkbox" id="inStockOnly"
                           @bind="_inStockOnly" />
                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
                </div>
            </div>

            <div class="filter-actions" style="margin-top: 1.5rem; display: flex; gap: 0.5rem;">
                <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
                <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
            </div>
        </aside>

        <!-- Main Content -->
        <main class="catalog-main" style="width: 75%;">
            <!-- Toolbar -->
            <div class="catalog-toolbar" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
                <div>
                    <label for="sortBy" class="form-label me-2" style="display: inline;">Sort by:</label>
                    <select id="sortBy" class="form-select d-inline-block" style="width: auto;" @onchange="OnSortChanged">
                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
