+++ b/tmp/sv-7242c2b3035d4780b714ba443d571d21/Components/Pages/Catalog.razor
@@ -1,0 +1,254 @@
+@page "/catalog"
+@rendermode InteractiveServer
+@inject IProductService ProductService
+
+<PageTitle>Product Catalog</PageTitle>
+
+<h1>Product Catalog</h1>
+
+@if (_error is not null)
+{
+    <div class="alert alert-danger" role="alert">
+        <strong>Error:</strong> @_error
+    </div>
+}
+else
+{
+    <div class="catalog-container" style="display: flex; gap: 1.5rem;">
+        <!-- Left Sidebar -->
+        <aside class="catalog-sidebar" style="width: 25%; min-width: 220px;">
+            <h4>Filters</h4>
+
+            <div class="filter-section">
+                <h5>Categories</h5>
+                @if (_categories is null)
+                {
+                    <p><em>Loading categories...</em></p>
+                }
+                else
+                {
+                    @foreach (var category in _categories)
+                    {
+                        <div class="form-check">
+                            <input class="form-check-input" type="checkbox" id="@($"cat-{category}")"
+                                   checked="@(_selectedCategories.Contains(category))"
+                                   @onchange="e => ToggleCategory(category, (bool)e.Value!)" />
+                            <label class="form-check-label" for="@($"cat-{category}")">@category</label>
+                        </div>
+                    }
+                }
+            </div>
+
+            <div class="filter-section" style="margin-top: 1rem;">
+                <h5>Price Range</h5>
+                <div class="mb-2">
+                    <label for="minPrice" class="form-label">Min Price</label>
+                    <input type="number" class="form-control" id="minPrice" step="0.01" min="0"
+                           @bind="_minPrice" placeholder="0.00" />
+                </div>
+                <div class="mb-2">
+                    <label for="maxPrice" class="form-label">Max Price</label>
+                    <input type="number" class="form-control" id="maxPrice" step="0.01" min="0"
+                           @bind="_maxPrice" placeholder="No limit" />
+                </div>
+            </div>
+
+            <div class="filter-section" style="margin-top: 1rem;">
+                <div class="form-check">
+                    <input class="form-check-input" type="checkbox" id="inStockOnly"
+                           @bind="_inStockOnly" />
+                    <label class="form-check-label" for="inStockOnly">In Stock Only</label>
+                </div>
+            </div>
+
+            <div class="filter-actions" style="margin-top: 1.5rem; display: flex; gap: 0.5rem;">
+                <button class="btn btn-primary" @onclick="ApplyFilters">Apply Filters</button>
+                <button class="btn btn-outline-secondary" @onclick="ClearFilters">Clear Filters</button>
+            </div>
+        </aside>
+
+        <!-- Main Content -->
+        <main class="catalog-main" style="width: 75%;">
+            <!-- Toolbar -->
+            <div class="catalog-toolbar" style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 1rem;">
+                <div>
+                    <label for="sortBy" class="form-label me-2" style="display: inline;">Sort by:</label>
+                    <select id="sortBy" class="form-select d-inline-block" style="width: auto;" @onchange="OnSortChanged">
+                        <option value="price_asc" selected="@(_sortBy == "price_asc")">Price: Low to High</option>
+                        <option value="price_desc" selected="@(_sortBy == "price_desc")">Price: High to Low</option>
+                        <option value="name_asc" selected="@(_sortBy == "name_asc")">Name: A-Z</option>
+                        <option value="rating_desc" selected="@(_sortBy == "rating_desc")">Rating: Highest</option>
+                    </select>
+                </div>
+                <div>
+                    @if (_result is not null && _result.TotalCount > 0)
+                    {
+                        var start = (_result.Page - 1) * _result.PageSize + 1;
+                        var end = Math.Min(_result.Page * _result.PageSize, _result.TotalCount);
+                        <span>Showing @start–@end of @_result.TotalCount products</span>
+                    }
+                </div>
+            </div>
+
+            <!-- Product Grid -->
+            @if (_loading)
+            {
+                <div class="d-flex justify-content-center py-5">
+                    <div class="spinner-border" role="status">
+                        <span class="visually-hidden">Loading...</span>
+                    </div>
+                </div>
+            }
+            else if (_result is null || _result.Items.Count == 0)
+            {
+                <div class="alert alert-info" role="alert">
+                    No products found matching your criteria.
+                </div>
+            }
+            else
+            {
+                <div class="product-grid" style="display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 1.5rem;">
+                    @foreach (var product in _result.Items)
+                    {
+                        <ProductCard Product="product"
+                                     OnProductSelected="OnProductSelected"
+                                     OnAddToCart="OnAddToCart" />
+                    }
+                </div>
+
+                <!-- Pagination -->
+                @{
+                    var totalPages = (int)Math.Ceiling((double)_result.TotalCount / _result.PageSize);
+                }
+                @if (totalPages > 1)
+                {
+                    <nav aria-label="Product pagination" style="margin-top: 2rem;">
+                        <ul class="pagination justify-content-center">
+                            <li class="page-item @(_currentPage == 1 ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(_currentPage - 1)" disabled="@(_currentPage == 1)">Previous</button>
+                            </li>
+                            @for (var i = 1; i <= totalPages; i++)
+                            {
+                                var pageNum = i;
+                                <li class="page-item @(pageNum == _currentPage ? "active" : "")">
+                                    <button class="page-link" @onclick="() => GoToPage(pageNum)">@pageNum</button>
+                                </li>
+                            }
+                            <li class="page-item @(_currentPage == totalPages ? "disabled" : "")">
+                                <button class="page-link" @onclick="() => GoToPage(_currentPage + 1)" disabled="@(_currentPage == totalPages)">Next</button>
+                            </li>
+                        </ul>
+                    </nav>
+                }
+            }
+        </main>
+    </div>
+}
+
+@code {
+    [Parameter]
+    public EventCallback<int> OnProductSelected { get; set; }
+
+    private List<string>? _categories;
+    private PagedResult<Product>? _result;
+    private bool _loading = true;
+    private string? _error;
+
+    // Filter state
+    private HashSet<string> _selectedCategories = new();
+    private decimal? _minPrice;
+    private decimal? _maxPrice;
+    private bool _inStockOnly;
+
+    // Paging and sorting
+    private string _sortBy = "price_asc";
+    private int _currentPage = 1;
+    private const int PageSize = 12;
+
+    protected override async Task OnInitializedAsync()
+    {
+        try
+        {
+            var categoriesTask = ProductService.GetCategoriesAsync();
+            var productsTask = LoadProducts();
+            await Task.WhenAll(categoriesTask, productsTask);
+            _categories = await categoriesTask;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private async Task LoadProducts()
+    {
+        _loading = true;
+        try
+        {
+            var filter = new ProductFilter(
+                Categories: _selectedCategories.Count > 0 ? _selectedCategories.ToList() : null,
+                MinPrice: _minPrice,
+                MaxPrice: _maxPrice,
+                InStockOnly: _inStockOnly
+            );
+            _result = await ProductService.SearchAsync(filter, _sortBy, _currentPage, PageSize);
+            _error = null;
+        }
+        catch (Exception ex)
+        {
+            _error = ex.Message;
+        }
+        finally
+        {
+            _loading = false;
+        }
+    }
+
+    private void ToggleCategory(string category, bool isChecked)
+    {
+        if (isChecked)
+            _selectedCategories.Add(category);
+        else
+            _selectedCategories.Remove(category);
+    }
+
+    private async Task ApplyFilters()
+    {
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task ClearFilters()
+    {
+        _selectedCategories.Clear();
+        _minPrice = null;
+        _maxPrice = null;
+        _inStockOnly = false;
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task OnSortChanged(ChangeEventArgs e)
+    {
+        _sortBy = e.Value?.ToString() ?? "price_asc";
+        _currentPage = 1;
+        await LoadProducts();
+    }
+
+    private async Task GoToPage(int page)
+    {
+        _currentPage = page;
+        await LoadProducts();
+    }
+
+    private async Task OnAddToCart(Product product)
+    {
+        // Placeholder for add to cart logic
+        await Task.CompletedTask;
+    }
+}
+

